"""Content patterns are review hints, never provider or protocol identity joins."""
import re


def _pattern(family, identity, expression, roles, protocols=()):
    return (family, identity, re.compile(expression, re.I | re.M), tuple(roles), tuple(protocols))


PATTERNS = [
    _pattern('HTTP_CLIENT', 'http-client-api',
             r'\b(?P<value>fetch|axios(?:\.[A-Za-z]+)?|(?:[\w]+\.)?(?:RestTemplate|RestClient|WebClient|HttpClient|OkHttpClient|HttpURLConnection|FeignClient|Feign|Retrofit|RestAssured|HttpRequest|XMLHttpRequest|EventSource)|(?:requests|httpx|aiohttp|urllib\.request|http|https)\.(?:get|post|put|patch|delete|request|urlopen|ClientSession)|(?:curl|wget))\b',
             ('consumer',), ('HTTP',)),
    _pattern('HTTP_CLIENT', 'http-wrapper-call',
             r'\b(?P<value>[\w$]*(?:client|http|api|request|service)[\w$]*\.(?:get|post|put|patch|delete|head|options|request|exchange|execute|getForObject|getForEntity|postForObject|postForEntity|retrieve|uri|url))\s*\(',
             ('consumer',), ('HTTP',)),
    _pattern('HTTP_PROVIDER', 'http-provider-declaration',
             r'(?P<value>@(?:RequestMapping|GetMapping|PostMapping|PutMapping|PatchMapping|DeleteMapping|Controller|RestController|WebServlet|Path|GET|POST|PUT|DELETE|PATCH)|\[(?:HttpGet|HttpPost|HttpPut|HttpPatch|HttpDelete|Route)|\b(?:app|router|server|route|routes|fastify)\.(?:get|post|put|patch|delete|head|options|route|use)|\b(?:http\.)?HandleFunc|\b(?:MapGet|MapPost|MapPut|MapDelete|MapMethods))\b',
             ('provider',), ('HTTP',)),
    _pattern('HTTP_ENDPOINT', 'http-provider-path',
             r'(?:@(?:[A-Za-z_][\w]*\.)?(?:route|get|post|put|patch|delete|RequestMapping|GetMapping|PostMapping|PutMapping|PatchMapping|DeleteMapping|Path)|\[(?:HttpGet|HttpPost|HttpPut|HttpPatch|HttpDelete|Route)|\b(?:app|router|server|route|routes|fastify)\.(?:get|post|put|patch|delete|head|options|route|use)|\b(?:http\.)?HandleFunc|\b(?:MapGet|MapPost|MapPut|MapDelete))\s*\(\s*(?:(?:value|path)\s*=\s*)?[\"\'](?P<value>[^\"\'\r\n]+)[\"\']',
             ('provider',), ('HTTP',)),
    _pattern('RPC_INTERFACE', 'rpc-api-or-schema',
             r'\b(?P<value>ManagedChannelBuilder|ServerBuilder|AbstractStub|ImplBase|(?:[A-Za-z_]\w*)Grpc|grpc\.(?:Dial|DialContext|NewClient|NewServer|insecure_channel|secure_channel|server|loadPackageDefinition)|GrpcClient|GrpcService|RpcClient|RpcService|JSONRPC|jsonrpc|TTransport|TBinaryProtocol|TMultiplexedProtocol|Thrift|ServiceClient|SOAPAction|WebService|WebMethod|WebServiceClient)\b|(?P<rpc>\brpc\s+\w+\s*\()',
             ('consumer', 'provider'), ('RPC',)),
    _pattern('MESSAGE_CLIENT', 'solace-client-api',
             r'\b(?P<value>JCSMPFactory|JCSMPSession|JCSMPProperties|XMLMessageProducer|XMLMessageConsumer|XMLMessageListener|BytesXMLMessage|SolaceMessagingService|SolaceConnectionFactory|SolConnectionFactory|SolJmsUtility|SolclientFactory|(?:solace\.)?(?:MessagingService|PersistentMessagePublisher|DirectMessagePublisher|PersistentMessageReceiver|DirectMessageReceiver)|com\.solacesystems(?:\.[\w.]+)?|solace\.(?:messaging|Session|SessionEventCode|Message|SolclientFactory)|solclientjs|solace-pubsubplus|solace-messaging)\b',
             ('consumer',), ('SOLACE',)),
    _pattern('MESSAGE_OPERATION', 'solace-operation',
             r'\b(?P<value>(?:jcsmp\w*|solace\w*|solSession|solFactory)\.(?:createProducer|createConsumer|createSession|createTopic|createQueue|createTopicDestination|createDurableQueueDestination|addSubscription|removeSubscription|send|publish|subscribe|connect)|(?:createDirectMessagePublisherBuilder|createPersistentMessagePublisherBuilder|createDirectMessageReceiverBuilder|createPersistentMessageReceiverBuilder|withSubscriptions))\s*\(',
             ('consumer',), ('SOLACE',)),
    _pattern('CONFIG_DECLARATION', 'messaging-property-binding',
             r'\b(?P<value>JCSMPProperties\.[A-Z_]+|(?:solace\.)?SessionProperties\.[A-Z_]+)\b',
             ('configuration',)),
    _pattern('MESSAGE_CHANNEL', 'message-destination-literal',
             r'\b(?:createTopic|createQueue|createTopicDestination|createDurableQueueDestination|createNonDurableQueueDestination|Topic\.of|Queue\.durableExclusiveQueue|Queue\.durableNonExclusiveQueue)\s*\(\s*[\"\'](?P<value>[^\"\'\r\n]+)[\"\']',
             ('configuration', 'destination')),
    _pattern('MESSAGE_CLIENT', 'messaging-client-api',
             r'\b(?P<value>KafkaTemplate|KafkaProducer|KafkaConsumer|KafkaListener|JmsTemplate|JmsListener|JMSContext|JMSProducer|JMSConsumer|MessageProducer|MessageConsumer|QueueConnectionFactory|TopicConnectionFactory|ActiveMQConnectionFactory|MQQueueManager|MQQueueConnectionFactory|MQConnectionFactory|RabbitTemplate|RabbitListener|RabbitMQ|amqplib|pika|aio_pika|MqttClient|MqttAsyncClient|Paho|mqtt\.(?:connect|Client)|StreamBridge|StreamListener|EnableBinding|MessageChannel|SubscribableChannel|BinderTypeRegistry)\b',
             ('consumer',), ('MESSAGING',)),
    _pattern('MESSAGE_CHANNEL', 'message-listener-channel',
             r'@(?:JmsListener|RabbitListener|KafkaListener)\s*\([\s\S]{0,400}?(?:destination|queues?|topics?)\s*=\s*(?:\{\s*)?[\"\'](?P<value>[^\"\'\r\n]+)[\"\']',
             ('consumer', 'subscriber'), ('MESSAGING',)),
    _pattern('MESSAGE_CHANNEL', 'camel-message-channel',
             r'\b(?:from|to|toD)\s*\(\s*[\"\'](?P<value>(?:solace|jms|amqp|amqps|mqtt|rabbitmq|kafka|activemq|ibmmq):[^\"\'\r\n]+)[\"\']',
             ('consumer',), ('MESSAGING',)),
    _pattern('DIRECTORY_CLIENT', 'directory-client-api',
             r'\b(?P<value>LdapTemplate|LdapOperations|LdapContextSource|InitialLdapContext|InitialDirContext|DirContext|LDAPConnection|LDAPConnectionPool|LdapConnection|LdapNetworkConnection|ldap3?\.(?:initialize|Connection|Server)|ldapjs|ldapts)\b',
             ('consumer',), ('DIRECTORY',)),
    _pattern('CACHE_CLIENT', 'cache-client-api',
             r'\b(?P<value>RedisTemplate|StringRedisTemplate|RedisClient|RedisClusterClient|RedissonClient|Jedis|JedisPool|LettuceConnectionFactory|ioredis|redis\.(?:createClient|Redis|from_url)|MemcachedClient|memcached|HazelcastInstance|HazelcastClient|IgniteClient|CacheManager)\b',
             ('consumer',), ('CACHE',)),
    _pattern('DATABASE_CLIENT', 'database-client-api',
             r'\b(?P<value>JdbcTemplate|NamedParameterJdbcTemplate|DataSource|DriverManager|getConnection|EntityManager|MongoClient|MongoTemplate|MongoRepository|mongoose|MongoDB|CassandraTemplate|CqlSession|DynamoDbClient|DynamoDBClient|CosmosClient|ElasticsearchClient|OpenSearchClient|SearchClient|PrismaClient|create_engine|psycopg2?|asyncpg|pg\.Pool|mysql\.(?:createConnection|createPool)|sequelize|knex|sqlalchemy)\b',
             ('consumer',), ('DATABASE',)),
    _pattern('STORAGE_CLIENT', 'storage-client-api',
             r'\b(?P<value>S3Client|S3AsyncClient|AmazonS3|BlobServiceClient|BlobContainerClient|BlobClient|ShareServiceClient|StorageClient|MinioClient|boto3\.(?:client|resource)|GoogleCloudStorage|google\.cloud\.storage|PutObjectRequest|GetObjectRequest|UploadPartRequest)\b',
             ('consumer',), ('STORAGE',)),
    _pattern('FILE_CLIENT', 'file-client-api',
             r'\b(?P<value>FileInputStream|FileOutputStream|RandomAccessFile|FileChannel|FileReader|FileWriter|Files\.(?:read\w*|write\w*|copy|move|newInputStream|newOutputStream)|fs\.(?:readFile\w*|writeFile\w*|createReadStream|createWriteStream)|FTPClient|FTPSClient|SFTPClient|ChannelSftp|SftpRemoteFileTemplate|ssh2-sftp-client|paramiko\.(?:SSHClient|SFTPClient)|ftplib\.FTP|file://)\b',
             ('consumer',), ('FILE',)),
    _pattern('NETWORK_CLIENT', 'network-client-api',
             r'\b(?P<value>Socket|ServerSocket|DatagramSocket|DatagramChannel|SocketChannel|TcpClient|TcpListener|UdpClient|WebSocket|WebSocketClient|SockJS|Stomp|stompjs|net\.connect|net\.createConnection|socket\.(?:socket|create_connection)|net\.Dial|net\.Listen|tls\.connect|QUdpSocket|QTcpSocket)\b',
             ('consumer', 'provider'), ('NETWORK',)),
    _pattern('API_CONTRACT', 'api-contract-declaration',
             r'(?P<value>\b(?:openapi|swagger|asyncapi)\s*[\"\']?\s*[:=]|\bsyntax\s*=\s*[\"\']proto[23][\"\']|^\s*(?:service|rpc)\s+\w+\s*[({]|<(?:\w+:)?(?:definitions|binding|portType|wsdl:definitions)\b|\btargetNamespace\s*=|\b(?:servers|channels|paths|operations)\s*[\"\']?\s*:)',
             ('contract',)),
    _pattern('API_CONTRACT', 'api-contract-path',
             r'^\s*[\"\']?(?P<value>/[^\s\"\':]{1,220})[\"\']?\s*:',
             ('contract', 'provider'), ('HTTP',)),
    _pattern('GRAPHQL_SCHEMA', 'graphql-schema-declaration',
             r'\b(?P<value>(?:(?:extend\s+)?(?:type|interface|enum|input|scalar|union)\s+[A-Za-z_]\w*|(?:extend\s+)?schema\s*\{|directive\s+@[A-Za-z_]\w*))',
             ('contract',), ('GRAPHQL',)),
    _pattern('GRAPHQL_OPERATION', 'graphql-operation-declaration',
             r'\b(?P<value>(?:query|mutation|subscription)\s+(?:[A-Za-z_]\w*\s*(?:\([^)]{0,500}\))?\s*)?\{)',
             ('contract',), ('GRAPHQL',)),
    _pattern('GRAPHQL_CLIENT', 'graphql-client-api',
             r'\b(?P<value>ApolloClient|ApolloProvider|ApolloServer|ApolloGateway|createHttpLink|HttpLink|GraphQLClient|GraphQLServer|gql|graphql_request|useQuery|useLazyQuery|useMutation|useSubscription)\b',
             ('consumer',), ('GRAPHQL',)),
    _pattern('PACKAGE_DECLARATION', 'package-manifest-declaration',
             r'(?P<value>[\"\'](?:dependencies|devDependencies|peerDependencies|optionalDependencies|require|require-dev)[\"\']\s*:|<(?:dependency|groupId|artifactId|PackageReference)\b|^\s*(?:implementation|api|compileOnly|runtimeOnly|require)\s*\(?\s*[\"\']|^\s*\[(?:dependencies|project\.dependencies|tool\.poetry\.dependencies)\]|\b(?:FROM|uses:)\s+[A-Za-z0-9_./@:-]+)',
             ('package',)),
    _pattern('MODULE_IMPORT', 'namespace-import',
             r'^\s*(?:import|using)\s+(?:static\s+)?(?P<value>[A-Za-z_][\w.]*(?:\.\*)?)\s*;',
             ('dependency',)),
    _pattern('CALL_HINT', 'generic-boundary-operation',
             r'\b(?P<value>[A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*\.(?:send|sendAsync|sendMessage|publish|subscribe|consume|receive|receiveAsync|connect|openConnection|createProducer|createConsumer|createSession|addSubscription|request|invoke|call|execute|exchange))\s*\(',
             ('consumer',)),
]
